-- RP-149: the Evals product (eval suites, runs, scorers), behind FF_EVALS. Generated by drizzle-kit
-- from views/evals/schema.ts and views/scorers/schema.ts, then written as upstream ratel-cloud 0088,
-- 0089, 0090, 0098-0105 end state: IF NOT EXISTS, with the foreign keys inline, so a database migrated
-- by ratel-cloud already has the 9 tables and this is a no-op there. New, empty tables on a fresh
-- database: no lock on a hot table, nothing to backfill.
CREATE TABLE IF NOT EXISTS "evals" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"name" text NOT NULL,
	"source_turn_id" uuid,
	"source_case_id" uuid,
	"message" text NOT NULL,
	"earlier_messages" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"turns" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"checks" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"expected_tool" text,
	"criteria" text DEFAULT '' NOT NULL,
	"fixed_answers" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"system_prompt" text,
	"tools" jsonb,
	"context" jsonb,
	"generated" jsonb,
	"suggestion_reason" jsonb,
	"edited" jsonb,
	"run_settings" jsonb,
	"opening" jsonb,
	"status" text DEFAULT 'suggested' NOT NULL,
	"origin" text NOT NULL,
	"created_by" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "evals_project_source_case_key" UNIQUE("project_id","source_case_id"),
	CONSTRAINT "evals_status_check" CHECK ("evals"."status" in ('suggested', 'approved', 'archived')),
	CONSTRAINT "evals_origin_check" CHECK ("evals"."origin" in ('auto', 'issue', 'user', 'fix', 'session')),
	CONSTRAINT "evals_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "evals_project_status_idx" ON "evals" USING btree ("project_id","status");
