	CONSTRAINT "eval_runs_fix_check" CHECK (("eval_runs"."kind" = 'simulation') = ("eval_runs"."fix_id" is not null)),
	CONSTRAINT "eval_runs_count_check" CHECK ("eval_runs"."eval_count" >= 0),
	CONSTRAINT "eval_runs_project_id_projects_id_fk" FOREIGN KEY ("project_id") REFERENCES "public"."projects"("id") ON DELETE cascade ON UPDATE no action
